        db $01, $00, $00, $04, $00, $00, $00, $00, $00, $00, $00, $00, $04, $00, $00, $01
        db $01, $00, $02, $02, $02, $02, $03, $00, $00, $00, $02, $02, $02, $02, $00, $01
        db $01, $00, $00, $00, $00, $00, $03, $00, $00, $00, $00, $00, $00, $00, $00, $01
        db $01, $00, $00, $00, $00, $00, $03, $00, $00, $04, $00, $00, $00, $00, $00, $01
        db $01, $00, $00, $00, $00, $00, $03, $00, $02, $02, $02, $02, $02, $00, $00, $01
        db $01, $00, $00, $04, $00, $00, $03, $00, $00, $00, $00, $00, $00, $00, $00, $01
        db $01, $00, $00, $00, $00, $00, $03, $00, $00, $00, $00, $00, $00, $04, $00, $01
        db $01, $00, $00, $00, $00, $00, $03, $00, $00, $00, $00, $00, $00, $00, $00, $01
        db $01, $02, $02, $02, $02, $02, $02, $02, $02, $02, $02, $02, $02, $02, $02, $01
